	/** 
	 * jumpstart the process by instantiating2 Patient
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		patientId = PatientService.getPatientInstance()
		.createPatient( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		PatientService.getPatientInstance()
				.createPatient( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.patientSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Patient : " + successValue.getPatientId());
							  if (successValue.getPatientId().equals(patientId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfPatientList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Patient test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on patient consumed")
					);
			subscriber.patientSubscribe( patientId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Patient : " + successValue.getPatientId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfPatientList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on patient for patientId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Patient. 
	 */
	protected Patient read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Patient" );

		Patient entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Patient with primary key" );
		msg.append( patientId );
		
		PatientFetchOneSummary fetchOneSummary = new PatientFetchOneSummary( patientId );

		try {
			entity = PatientService.getPatientInstance().getPatient( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Patient " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Patient.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Patient." );

		StringBuilder msg = new StringBuilder( "Failed to update a Patient : " );        
		Patient entity = read();
		UpdatePatientCommand command = generateUpdateCommand();
		command.setPatientId(entity.getPatientId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Patient." );

			// for use later on...
			patientId = entity.getPatientId();

			PatientService proxy = PatientService.getPatientInstance();  

			proxy.updatePatient( command ).get();

			LOGGER.info( "-- Successfully saved Patient - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + patientId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Patient.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Patient." );

		Patient entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Patient with id " + patientId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Patient with id " + patientId );

			throw e;
		}

		try{
			PatientService.getPatientInstance().delete( new DeletePatientCommand( entity.getPatientId() ) ).get();
			LOGGER.info( "-- Successfully deleted Patient with id " + patientId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Patient with id " + patientId );

			throw e;
		}
	}

	/**
	 * get all Patients.
	 */
	protected List<Patient> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Patients:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Patient : " );        
		List<Patient> collection  = new ArrayList<>();

		try {
			// call the static get method on the PatientService
			collection = PatientService.getPatientInstance().getAllPatient();
			assertNotNull( collection, "An Empty collection of Patient was incorrectly returned.");
			
			// Now print out the values
			Patient entity = null;            
			Iterator<Patient> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getPatientId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

